using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PurifyCorruptReceiveCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PurifyCorruptReceiveCustomDescription", order = 0)]
public class PurifyCorruptReceiveCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string iD = battleAction.TargetData.TargetCorruptPurifyID + "Receive";
		string text = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(battleAction.BaseBattleActionData.ActionIDDescription + "Receive");
		if (amountModified == EffectsValues.NO_VALUE_STRING || amountModified == "-1")
		{
			amountModified = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedX();
		}
		if (amountModified != "-4")
		{
			text = Smart.Format(text, amountModified);
		}
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(iD), text);
	}
}
